    public static class OlgaTokarczuk
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Moje dzieła są wystarczająco dobrze zrobione, żeby żyć, ale też tak niedoskonałe, żeby nic ze swojego życia nie rozumieć. Przykro mi, że nie mogą być szczęśliwi.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Mówić do kogoś, kto nie rozumie, to próbować otworzyć zamek źdźbłem trawy, to kroić chleb gałązką bazylii, wkręcać żarówkę w ptasie gniazdo, wkładać dyskietkę między dwa kamienie. Daremnie.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Zgubiła ją własna duma; to jedyny grzech bogów.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Celem mojej pielgrzymki jest zawsze inny pielgrzym.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Gdyby można było spojrzeć na świat bez żadnej ochrony, uczciwie i odważnie – pękłyby nam serca.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Prześwietlić świat jak rentgenem i ujrzeć tam szkielet-Pustki.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Och, ludzie ciągle potrzebują rzeczy niezwykłych, cudów, szaleństw. I po co? Żeby z jeszcze większą gorliwością akceptować swoje zwyczajne życie.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Skoro jest prawo i porządek, musi być także coś, co to prawo dopełnia i ogranicza zarazem – chaos i nieistnienie. Nieistnienie i chaos.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Tu i teraz jesteśmy ślepi i nigdy nie wiemy, co jest naprawdę ważne.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Rewolucje nie lubią wariatów, bo same są śmiertelnie poważne.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Wszystko jest zawsze prostsze, niż się na początku wydaje.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Zdaje się, że nic nie budzi wśród mężczyzn takiego współczucia jak samotna kobieta.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Gdy przepisujemy i cytujemy, budujemy gmach wiedzy i rozmnażamy ją jak moje warzywa czy jabłonki. Przepisywanie jest jak szczepienie drzewa; cytowanie – jak wysiewanie nasion.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Skoro można pomyśleć, że może być lepiej, to znaczy, że już jest lepiej.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Bóg jest w każdym procesie. Bóg pulsuje w przemianach. Raz jest, raz jest go mniej, ale czasem nie ma go wcale. Bóg bowiem przejawia się nawet w tym, że go nie ma.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Kto raz widział granice świata, ten najboleśniej doświadczać będzie swego uwięzienia.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Młodość w swoim natężeniu, w swojej mocy, męczy się sobą. Którejś nocy czy któregoś poranka człowiek przechodzi granice, osiąga swój szczyt i robi pierwszy krok w dół ku śmierci.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Może młynki do kawy są osią rzeczywistości?", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Myślał, że starość otwiera to trzecie okno, którym widzi się wszystko na wskroś, które pozwala rozumieć, jak działa świat. Ale nic się nie wyjaśniło.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Największym oszustwem młodości jest wszelki optymizm, uporczywa wiara w to, że we wszystkim jest postęp.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "W niewiedzy, że się istnieje jest wyzwolenie od czasu i śmierci.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Byli to rzeczywiście ludzie ze studni – tacy, co wpadli do niej dawno temu i teraz na jej dnie urządzali sobie swoje życie, myśląc, że studnia jest całym światem.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Historie życia nie są tematem do dyskusji. Powinno się ich wysłuchać i zrewanżować się tym samym.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "My mamy światopogląd, a Zwierzęta światoczucie, wiesz?", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Najlepiej rozmawia się samemu ze sobą. Przynajmniej nie dochodzi do nieporozumień.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Smutek jest ważnym słowem w definicji świata. Leży u podstaw wszystkiego, jest piątym żywiołem, kwintesencją.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Więzienie nie tkwi na zewnątrz, ale jest w środku każdego z nas. Może jest tak, że nie umiemy bez niego żyć.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Wszystko przeminie. Mądry Człowiek wie o tym od samego początku i niczego nie żałuje.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Z punktu widzenia natury nie ma istot pożytecznych i niepożytecznych. To tylko niemądre rozróżnienie stosowane przez ludzi.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Zdrowie jest stanem niepewnym i nie wróży nic dobrego. Lepiej jest być sobie spokojnie chorym, wtedy przynajmniej wiemy, na co umrzemy.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Parafraza Szekspirowskiego cytatu jak nigdy pasuje dzisiaj do tej kakofonicznej rzeczywistości: internet to coraz częściej opowieść idioty pełna wściekłości i wrzasku.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Czułam się tak, jakby jakieś niezależne siły zgłaszały swój akces do opisywanej przeze mnie historii, jakby sprzęgły się jakieś moce i niosły pomoc. Jakby światu zależało na napisaniu tej książki.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Obraz naszej historii, który mamy w głowie, jest jak zamek z papieru. Wygląda imponująco, ale palcem można wywiercić w nim dziurę. Potrzeba nam więc historycznej herezji.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Praca jest najuczciwszym stosunkiem do rzeczywistości.", Author = "Olga Tokarczuk" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Olga_Tokarczuk", Text = "Zakazałabym używania pięknego słowa „solidarność” społeczeństwu, które odmówiło pomocy uchodźcom.", Author = "Olga Tokarczuk" },
        };
    }
}